7	/**
8	 * ユーザーの出退勤を強制的に切り替える
9	 */
10	export async function forceToggleAttendance(userId: string) {
11	    const supabase = await createSupabaseAdminClient();
12	
13	    try {
14	        const { data: attendanceUser, error: attUserError } = await supabase
15	            .schema('attendance')
16	            .from('users')
17	            .select('supabase_auth_user_id, card_id')
18	            .eq('supabase_auth_user_id', userId)
19	            .single();
20	        
21	        if (attUserError || !attendanceUser) {
22	            return { success: false, message: '勤怠ユーザーが見つかりません。' };
23	        }
24	
25	        const { data: lastAttendance, error: lastAttendanceError } = await supabase
26	            .schema('attendance')
27	            .from('attendances')
28	            .select('type')
29	            .eq('user_id', attendanceUser.supabase_auth_user_id)
30	            .order('timestamp', { ascending: false })
31	            .limit(1)
32	            .maybeSingle();
33	        
34	        if (lastAttendanceError && lastAttendanceError.code !== 'PGRST116') {
35	            return { success: false, message: lastAttendanceError.message };
36	        }
37	
38	        const newType = lastAttendance?.type === 'in' ? 'out' : 'in';
39	
40	        const { error: insertError } = await supabase
41	            .schema('attendance')
42	            .from('attendances')
43	            .insert({ 
44	                user_id: attendanceUser.supabase_auth_user_id, 
45	                type: newType, 
46	                card_id: attendanceUser.card_id 
47	            });
48	
49	        if (insertError) {
50	            return { success: false, message: insertError.message };
51	        }
52	
53	        revalidatePath('/admin');
54	        revalidatePath('/dashboard/teams', 'page');
55	        revalidatePath('/dashboard/layout');
56	        
57	        return { 
58	            success: true, 
59	            message: `ユーザーを強制的に${newType === 'in' ? '出勤' : '退勤'}させました。` 
60	        };
61	    } catch (error) {
62	        console.error('Error in forceToggleAttendance:', error);
63	        return { success: false, message: '予期しないエラーが発生しました。' };
64	    }
65	}
66	
67	/**
68	 * 日次出勤ログを全件取得
69	 */
70	export async function getAllDailyLogoutLogs() {
71	    const supabase = await createSupabaseAdminClient();
72	    return supabase
73	        .schema('attendance')
74	        .from('daily_logout_logs')
75	        .select('*')
76	        .order('timestamp', { ascending: false });
77	}
