79	/**
80	 * 月次出席サマリーを取得
81	 */
82	export async function getMonthlyAttendanceSummary(month: Date) {
83	    const supabase = await createSupabaseAdminClient();
84	    const start = format(startOfMonth(month), 'yyyy-MM-dd');
85	    const end = format(endOfMonth(month), 'yyyy-MM-dd');
86	
87	    const { data, error } = await (supabase as any).rpc('get_monthly_attendance_summary', { 
88	        start_date: start, 
89	        end_date: end 
90	    });
91	
92	    if (error) {
93	        console.error('Error fetching monthly attendance summary:', error);
94	        return {};
95	    }
96	
97	    type DailySummary = {
98	        total: number;
99	        byTeam: Record<string, { name: string; total: number; byGeneration: Record<number, number> }>;
100	    };
101	
102	    const summary: Record<string, DailySummary> = {};
103	
104	    if (data) {
105	        for (const record of (data as any[])) {
106	            const { date, team_id, team_name, generation, count } = record;
107	            if (!date || !team_id || !team_name || count === null) continue;
108	
109	            const dateKey = format(new Date(date), 'yyyy-MM-dd');
110	
111	            if (!summary[dateKey]) {
112	                summary[dateKey] = { total: 0, byTeam: {} };
113	            }
114	            
115	            if (!summary[dateKey].byTeam[team_id]) {
116	                summary[dateKey].byTeam[team_id] = { name: team_name, total: 0, byGeneration: {} };
117	            }
118	            
119	            summary[dateKey].total += count;
120	            summary[dateKey].byTeam[team_id].total += count;
121	            summary[dateKey].byTeam[team_id].byGeneration[generation] = count;
122	        }
123	    }
124	
125	    return summary;
126	}
127	
128	/**
129	 * 日別出勤数を取得
130	 */
131	export async function getDailyAttendanceCounts(month: Date) {
132	    const supabase = await createSupabaseAdminClient();
133	    const start = format(startOfMonth(month), 'yyyy-MM-dd');
134	    const end = format(endOfMonth(month), 'yyyy-MM-dd');
135	
136	    const { data, error } = await (supabase as any).rpc('get_monthly_attendance_summary', { 
137	        start_date: start, 
138	        end_date: end 
